-- REPETITION (lecture seule) -- genere par phase2/checks/dates_annulation_generer_patch_2026-11-25.py (son mot du 25/11)
select (select string_agg(app_affaire_id || '=' || coalesce(date_annulation_app, '-'), ' ' order by app_affaire_id) from public.app_affaire_ledger where app_affaire_id in (27195, 4385, 27134, 16377, 17387, 24450, 20073)) as les_7_compromis,
  (select count(*) from public.app_classeur_realignement_journal where lot = 'dates_annulation_2026-11-25') as journal_attendu_7,
  (select md5(coalesce(string_agg(concat_ws('|', app_affaire_id, kind, state, coalesce(date_annulation_app, '-'), coalesce(motif_annulation_app, '-'), coalesce(vente_reglee_app, '-'), coalesce(numero_facture_app, '-'), coalesce(honoraires_entree_app::text, '-')), ';' order by app_affaire_id), '')) from public.app_affaire_ledger where app_affaire_id in (27195, 4385, 27134, 16377, 17387, 24450, 20073)) as empreinte_apres;
